export const FISCAL_KINDS = ['simplified_invoice', 'standard_invoice', 'receipt', 'credit_note', 'debit_note'] as const;
export type FiscalKind = (typeof FISCAL_KINDS)[number];

export const fiscalDocumentQuery = z.object({
  kind: z.enum(FISCAL_KINDS).optional(),
  branchId: uuid.optional(),
  orderId: uuid.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});

export const issueFiscalDocument = z.object({ orderId: uuid });

export interface FiscalLine {
  /** Internal item code (product id) — used as the ETA internalCode / item code suffix. */
  code: string | null;
  name: string;
  nameAr: string | null;
  kind: 'item' | 'delivery_fee' | 'service_charge' | 'adjustment';
  quantity: number;
  unitPriceMinor: number;
  discountMinor: number;
  netMinor: number;
  vatMinor: number;
  grossMinor: number;
  vatRateBp: number;
}

export interface FiscalDocumentView {
  id: string;
  branchId: string;
  orderId: string | null;
  kind: FiscalKind;
  series: string;
  number: string;
  counterValue: number;
  uuid: string;
  previousHash: string | null;
  documentHash: string;
  qrPayload: string | null;
  currency: string;
  subtotalMinor: number;
  taxMinor: number;
  totalMinor: number;
  buyer: Record<string, unknown>;
  lines: FiscalLine[];
  issuedAt: string;
  status: string;
  referencesDocumentId: string | null;
  authority: 'zatca' | 'eta' | null;
  lastSubmission: { mode: string; status: string; submittedAt: string } | null;
}

// ---------------------------------------------------------------------------
// Licences & certificates (compliance_documents)
// ---------------------------------------------------------------------------
const reminderDays = z.array(z.number().int().min(0).max(365)).max(6)
  .transform((d) => [...new Set(d)].sort((a, b) => b - a));

export const licenceInput = z.object({
  kind: z.enum(LICENCE_KINDS),
  title: text(200),
  branchId: uuid.optional().nullable(),
  referenceNumber: optionalText(100),
  issuingAuthority: optionalText(200),
  issuedOn: isoDate.optional().nullable(),
  expiresOn: isoDate.optional().nullable(),
  reminderDays: reminderDays.optional(),
  notes: optionalText(2000),
}).refine((v) => !v.issuedOn || !v.expiresOn || v.expiresOn >= v.issuedOn, { message: 'Expiry must be on or after the issue date', path: ['expiresOn'] });
export type LicenceInput = z.infer<typeof licenceInput>;

export const licenceUpdate = z.object({
  kind: z.enum(LICENCE_KINDS).optional(),
  title: text(200).optional(),
  branchId: uuid.optional().nullable(),
  referenceNumber: optionalText(100),
  issuingAuthority: optionalText(200),
  issuedOn: isoDate.optional().nullable(),
  expiresOn: isoDate.optional().nullable(),
  reminderDays: reminderDays.optional(),
  notes: optionalText(2000),
});
export type LicenceUpdate = z.infer<typeof licenceUpdate>;

export type ExpiryStatus = 'expired' | 'expiring' | 'valid' | 'no_expiry';

/** Days from `today` (YYYY-MM-DD) to `expiresOn`; negative when expired. */
export function daysUntil(expiresOn: string, today: string): number {
  return Math.round((Date.parse(`${expiresOn}T00:00:00Z`) - Date.parse(`${today}T00:00:00Z`)) / 86_400_000);
}

export function expiryStatus(expiresOn: string | null, today: string, windowDays = 30): ExpiryStatus {
  if (!expiresOn) return 'no_expiry';
  const d = daysUntil(expiresOn, today);
  if (d < 0) return 'expired';
  return d <= windowDays ? 'expiring' : 'valid';
}

export interface LicenceView {
  id: string;
  branchId: string | null;
  kind: LicenceKind;
  title: string;
  referenceNumber: string | null;
  issuingAuthority: string | null;
  issuedOn: string | null;
  expiresOn: string | null;
  daysToExpiry: number | null;
  expiryStatus: ExpiryStatus;
  reminderDays: number[];
  reminders: Array<{ daysBefore: number; remindOn: string; status: string; sentAt: string | null }>;
  notes: string | null;
  file: { mediaId: string; contentType: string; url: string } | null;
  createdAt: string;
  updatedAt: string;
}
